style.css:
@-moz-document domain("discord.com") {
/* General background */
    body, .appMount-3lHmkl {
        background-color: #1a0b1f !important;
        color: #fcd6f6 !important;
        font-family: "Comic Neue", "Fira Code", cursive !important;
    }

    /* Server list background */
    .guilds-2JjMmN {
        background-color: #2a1133 !important;
    }

    /* Channel list background */
    .sidebar-1tnWFu {
        background-color: #2d1240 !important;
    }

    /* Chat area */
    .chat-2ZfjoI {
        background-color: #1a0b1f !important;
    }

    /* Message bubble styling */
    .message-2CShn3 {
        background-color: rgba(255, 192, 203, 0.07) !important;
        border-left: 4px solid #e97ec3 !important;
        border-radius: 10px;
        margin: 3px 0;
        padding-left: 6px;
    }

    /* Headers and text accents */
    h1, h2, h3, h4, h5, h6, strong {
        color: #ffb6ea !important;
    }

    /* Selected channel and highlights */
    .wrapper-1ucjTd.selected-1HYmZZ {
        background-color: #7e2b89 !important;
    }

    /* Links and mentions */
    a, .mention {
        color: #e97ec3 !important;
    }

    /* Scrollbars - purple & cute */
    ::-webkit-scrollbar {
        width: 8px;
    }

    ::-webkit-scrollbar-track {
        background: #2d1240;
    }

    ::-webkit-scrollbar-thumb {
        background-color: #e97ec3;
        border-radius: 4px;
    }

    /* Hide Nitro tab */
    .premiumTab-39eQzY {
        display: none !important;
    }

    /* Cute hover effects */
    .button-38aScr:hover {
        background-color: #e97ec3 !important;
        color: #1a0b1f !important;
    }

    /* Kuromi-themed emoji reaction bar */
    .reaction-3vwAF2 {
        background-color: #3c1a4f !important;
        border: 1px solid #e97ec3 !important;
    }
}
